-- Deities and Demigods: Olympian pantheon cleric options and mystery cults.
-- Source: Deities and Demigods (2002), Chapter 4, pp. 100, 113-115, 132.
-- These are religion/campaign mechanics rather than deity stat blocks.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

WITH desired(slug,name,page,description,rules_text,kind,tags,mechanics) AS (VALUES
('dd-olympian-pantheon-cleric-options','Olympian Pantheon Cleric Options','100',
 'Rules for clerics who select the entire tight Olympian pantheon rather than an individual Olympian deity as patron.',
 'All mortals are expected to revere the twelve central Olympian deities. A cleric may select the whole pantheon as patron, may be of any alignment, may choose two domains from the pantheon list subject to the normal alignment-domain restrictions, and chooses one listed weapon form for spiritual weapon.',
 'pantheon-cleric-options',
 '["deities-and-demigods","olympian","pantheon","cleric-options"]',
 '{"pantheonSlug":"olympian","wholePantheonPatronAllowed":true,"requiredGeneralReverence":{"appliesToAllMortals":true,"centralDeities":["zeus","aphrodite","apollo","ares","artemis","athena","demeter","hephaestus","hera","hermes","hestia","poseidon"]},"clericAlignment":"any","domains":["Air","Animal","Artifice","Chaos","Charm","Community","Creation","Death","Destruction","Earth","Evil","Fire","Good","Healing","Knowledge","Law","Luck","Madness","Magic","Nobility","Plant","Protection","Strength","Sun","Travel","Trickery","War","Water","Weather"],"spiritualWeaponForms":["dagger","greatclub","light mace","longsword","quarterstaff","short sword","spear (any kind)","trident","unarmed strike","warhammer"],"raceRecommendations":{"human":"by class and alignment","dwarf":["hephaestus","hades","or by class and alignment"],"elf":["apollo","artemis","or by class and alignment"],"gnome":["hermes","hephaestus","or by class and alignment"],"half-elf":"by class and alignment","half-orc":["ares","or by class and alignment"],"halfling":["tyche","or by class and alignment"]},"classRecommendations":{"bard":[{"deity":"aphrodite","alignment":"CG"},{"deity":"apollo","alignment":"CG"},{"deity":"dionysus","alignment":"CN"}],"barbarian":[{"deity":"zeus","alignment":"CG"},{"deity":"pan","alignment":"CN"},{"deity":"ares","alignment":"CE"}],"cleric":"any","druid":[{"deity":"artemis","alignment":"NG"},{"deity":"demeter","alignment":"N"},{"deity":"pan","alignment":"CN"},{"deity":"poseidon","alignment":"CN"}],"fighter":[{"deity":"athena","alignment":"LG"},{"deity":"hercules","alignment":"CG"},{"deity":"nike","alignment":"LN"},{"deity":"poseidon","alignment":"CN"},{"deity":"ares","alignment":"CE"}],"monk":[{"deity":"athena","alignment":"LG"},{"deity":"nike","alignment":"LN"}],"paladin":[{"deity":"athena","alignment":"LG"}],"ranger":[{"deity":"athena","alignment":"LG"},{"deity":"zeus","alignment":"CG"},{"deity":"apollo","alignment":"CG"},{"deity":"artemis","alignment":"NG"}],"rogue":[{"deity":"hermes","alignment":"CG"},{"deity":"hera","alignment":"N"},{"deity":"tyche","alignment":"N"},{"deity":"dionysus","alignment":"CN"}],"sorcerer":[{"deity":"apollo","alignment":"CG"},{"deity":"hecate","printedAlignment":"LE","actualDeityAlignment":"NE"}],"wizard":[{"deity":"apollo","alignment":"CG"},{"deity":"hecate","printedAlignment":"LE","actualDeityAlignment":"NE"}],"illusionist":[{"deity":"hermes","alignment":"CG"}],"necromancer":[{"deity":"hades","alignment":"NE"}]},"sourceNotes":["Table 4-3 prints Hecate as LE in both the sorcerer and wizard rows although Table 4-1 and Hecate''s individual entry identify her as NE. The table value is retained as printed metadata rather than treated as a deity-alignment override."]}'),

('dd-eleusinian-mysteries','The Eleusinian Mysteries','113',
 'Demeter-centered mystery cult whose initiates ritually reenact Persephone''s descent and return and expect a blessed afterlife with Demeter on Olympus.',
 'Clerics devoted specifically to Demeter are always members of the Eleusinian Mysteries. Initiation reenacts the Persephone myth as a personal descent-and-return experience. Demeter''s avatar is said to appear at the ritual climax and bless initiates. The inner rites are utterly secret, with revelation punishable by death. The source states an afterlife promise but gives no numerical character bonus.',
 'mystery-cult',
 '["deities-and-demigods","olympian","demeter","eleusinian-mysteries","mystery-cult"]',
 '{"pantheonSlug":"olympian","cult":"Eleusinian Mysteries","patron":"demeter","center":"Eleusis","clericsOfPatronMustJoin":true,"centralMyth":{"figures":["Demeter","Persephone","Hades","Demophoon"],"theme":"Persephone is abducted into Hades; Demeter searches and mourns; Persephone returns for part of each year, explaining the cycle of fertility and barrenness."},"initiation":{"reenactsMyth":true,"stages":["celebrate as Persephone gathers flowers","learn of the abduction and cease revelry","carry torches while reenacting Demeter''s search","identify with Demophoon and the promise of immortality","symbolically descend to the underworld with Persephone","symbolically rise to Olympus with Demeter"],"avatarAppearance":"Demeter''s avatar is said to appear at the climax and bestow her blessing."},"secrecy":{"innerRites":"utterly secret","disclosurePenalty":"death"},"afterlifeBelief":"Initiates believe they will not become ordinary shades in Hades but will dwell with Demeter on Olympus in eternal bliss.","explicitNumericCharacterBonus":null,"sourceFidelityNote":"The source describes blessing, initiation, secrecy, and afterlife belief but does not assign a numerical feat-like or spell-like bonus to ordinary initiates; none is invented here."}'),

('dd-orphic-mysteries','The Orphic Mysteries','115',
 'Dionysian mystery cult teaching the secret Zagreus myth and ritual participation in Dionysus-Zagreus''s life, death, and rebirth.',
 'Clerics devoted specifically to Dionysus are always members of the Orphic Mysteries. Initiates reenact the Zagreus/Dionysus cycle, symbolically die to their old lives and rise to new lives, and believe they encounter Dionysus or his avatar in the rites. They expect to dwell with Dionysus-Zagreus on Olympus after death. The source gives no numerical character bonus for ordinary initiation.',
 'mystery-cult',
 '["deities-and-demigods","olympian","dionysus","orphic-mysteries","mystery-cult","zagreus"]',
 '{"pantheonSlug":"olympian","cult":"Orphic Mysteries","patron":"dionysus","clericsOfPatronMustJoin":true,"secretMyth":{"source":"Orpheus","zagreusParents":["Zeus","Persephone"],"events":["Hera sends Titans to kill Zagreus","Zagreus shapechanges while fleeing","Titans tear apart and consume Zagreus in bull form","Zeus incinerates the Titans","Humanity is formed from the Titans'' ashes and therefore carries a divine spark from Zagreus","Zagreus'' rescued heart becomes the origin of Dionysus through Semele","Dionysus is the twice-born reincarnation of Zagreus","Dionysus later retrieves Semele from the underworld and brings her to Olympus"]},"initiation":{"reenactsMyth":true,"symbolicDeathAndRebirth":true,"claimedDivineEncounter":"Initiates believe they meet Dionysus or his avatar firsthand."},"postInitiation":"Initiates embrace a life of carefree celebration and orgiastic frenzy.","afterlifeBelief":"Initiates look forward to life with Dionysus-Zagreus on Olympus after death.","explicitNumericCharacterBonus":null,"sourceFidelityNote":"The source gives ritual, doctrinal, and afterlife effects but no numerical feat-like or spell-like benefit to ordinary initiates; none is invented here."}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,d.rules_text,
  0,NULL,1,'religion',d.kind,0,1,'dd-olympian-pantheon',NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
